cat > /tmp/send_email.js << 'EOF'
const fs = require('fs');
const path = require('path');

const TESTBED_DIR = '/workspace/testbed';

const sender = 'alice';
const recipient = 'priya';
const subject = 'Onboarding Equipment Status Review - September 8';
const content = `Hi Priya,

I've scheduled an "Onboarding Equipment Status Review" meeting for Tuesday, September 8, 2026, from 2:00 PM to 3:00 PM.

The purpose of this meeting is to review the status of equipment provisioning for upcoming onboarding. I wanted to make sure you're aware and can plan accordingly, especially given our other onboarding coordination events that day.

Here's the schedule for context:
- New Hire Readiness Check: Sep 8, 10:00 AM – 11:00 AM
- Onboarding Equipment Status Review: Sep 8, 2:00 PM – 3:00 PM
- Contractor Day-One Setup Check: Sep 5, 3:00 PM – 4:00 PM

Please let me know if you have any questions or if there's anything you'd like added to the agenda.

Best regards,
Alice`;

// Create directories
for (const folder of [sender, recipient]) {
    const dir = path.join(TESTBED_DIR, 'emails', folder);
    fs.mkdirSync(dir, { recursive: true });
}

// Build simple .eml content
const eml = `From: ${sender}@example.com
To: ${recipient}@example.com
Subject: ${subject}
MIME-Version: 1.0
Content-Type: text/plain; charset="utf-8"

${content}`;

for (const folder of [sender, recipient]) {
    const emailFile = path.join(TESTBED_DIR, 'emails', folder, `${subject}.eml`);
    fs.writeFileSync(emailFile, eml);
}

console.log(`Successfully sent email to ${recipient}.`);
EOF
node /tmp/send_email.js
